import{_ as a,o as r,c as o,a5 as e}from"./chunks/framework.CXroN2RO.js";const m=JSON.parse('{"title":"ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較","description":"","frontmatter":{"title":"ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"C++は「解放の責任を型と設計で表す」(RAII・所有権)、C#は「解放をランタイムが後で回収する」(GC)。どちらもメモリ管理であり、コストの払い方が違うだけです。この比較を正しく理解すると、UnityのGC Alloc対策がC++の知識で説明でき、逆にC++の設計がC#の経験で腑に落ちます。"}},"headers":[],"relativePath":"runtime/memory/gc-and-csharp-comparison.md","filePath":"runtime/memory/gc-and-csharp-comparison.md"}'),l={name:"runtime/memory/gc-and-csharp-comparison.md"};function n(d,t,i,s,c,h){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="ガベージコレクションとの違い-—-c-の管理ヒープ・unityのgc-allocとの比較" tabindex="-1">ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較 <a class="header-anchor" href="#ガベージコレクションとの違い-—-c-の管理ヒープ・unityのgc-allocとの比較" aria-label="Permalink to &quot;ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>C++は「<strong>解放の責任を型と設計で表す</strong>」(RAII・所有権)、C#は「<strong>解放をランタイムが後で回収する</strong>」(GC)。どちらもメモリ管理であり、<strong>コストの払い方が違うだけ</strong>です。この比較を正しく理解すると、UnityのGC Alloc対策がC++の知識で説明でき、逆にC++の設計がC#の経験で腑に落ちます。</p><h2 id="c-の管理ヒープの仕組み-概要" tabindex="-1">C#の管理ヒープの仕組み(概要) <a class="header-anchor" href="#c-の管理ヒープの仕組み-概要" aria-label="Permalink to &quot;C#の管理ヒープの仕組み(概要)&quot;">​</a></h2><ul><li><strong>確保は超高速</strong>: 管理ヒープはポインタを進めるだけ(前ページの<a href="/study/runtime/memory/allocators-and-pools.html">アリーナ</a>と同じ方式!)。<code>new</code> 自体はC++のmallocより速い</li><li><strong>回収がGCの仕事</strong>: 世代別GC——新しいオブジェクト(Gen0)を頻繁に小さく回収し、生き残りを昇格(Gen1→Gen2)。「大抵のオブジェクトはすぐ死ぬ」という経験則(世代仮説)の活用</li><li>回収時に<strong>コンパクション</strong>(生存者を詰め直す)——断片化が起きない代わり、オブジェクトが動く(だからC#ではポインタを直接持てない/pinningが要る)</li><li><strong>一時停止</strong>: 回収中はスレッドが止まる(または遅くなる)。これがフレームスパイク</li></ul><p>UnityのGC(Boehm GC)は上記の.NET GCと違い<strong>非世代・非コンパクション</strong>(保守的GC)で、より止まりやすい——「UnityでGC Allocが特に嫌われる」実装上の背景です(インクリメンタルGCで一時停止を分割する緩和策はある)。</p><h2 id="コスト構造の対比" tabindex="-1">コスト構造の対比 <a class="header-anchor" href="#コスト構造の対比" aria-label="Permalink to &quot;コスト構造の対比&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>C++(RAII/所有権)</th><th>C#(GC)</th></tr></thead><tbody><tr><td>確保</td><td>汎用newは遅め(特化アロケータで速くできる)</td><td>速い(bump allocation)</td></tr><tr><td>解放</td><td>決定的・即時(デストラクタ)</td><td>非決定的・まとめて(GC実行時)</td></tr><tr><td>支払いのタイミング</td><td><strong>常に少しずつ</strong>(設計時の頭脳労働+破棄処理)</td><td><strong>たまにまとめて</strong>(GCスパイク)</td></tr><tr><td>断片化</td><td>起きる(対策は自前 → <a href="/study/runtime/memory/allocators-and-pools.html">前ページ</a>)</td><td>コンパクションで解消(Unity Boehmは非対応)</td></tr><tr><td>循環参照</td><td>shared_ptrでは回収不能(weak_ptrで切る)</td><td>回収できる(到達可能性ベース)</td></tr><tr><td>メモリ以外の資源(ファイル等)</td><td>同じ仕組みで管理(RAII)</td><td>GCは面倒を見ない(Dispose/usingが別途必要)</td></tr><tr><td>「うっかり」の結果</td><td>リーク/UAF(未定義動作)</td><td>延命(論理リーク)/スパイク</td></tr></tbody></table><p><strong>重要な対称性</strong>: C++の事故は「早く死にすぎる」(UAF)、C#の事故は「死ななさすぎる」(意図せぬ延命・スパイク)。どちらの言語でも「<strong>寿命を設計する</strong>」ことからは逃げられません。</p><h2 id="unityのgc-alloc対策をc-の語彙で読み直す" tabindex="-1">UnityのGC Alloc対策をC++の語彙で読み直す <a class="header-anchor" href="#unityのgc-alloc対策をc-の語彙で読み直す" aria-label="Permalink to &quot;UnityのGC Alloc対策をC++の語彙で読み直す&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unityの定石</th><th>C++での対応物</th></tr></thead><tbody><tr><td>毎フレームnewしない・リスト再利用</td><td>フレームアロケータ/バッファ再利用</td></tr><tr><td>オブジェクトプール</td><td><a href="/study/game/patterns/object-pool.html">Object Pool</a>(同じ)</td></tr><tr><td>structで確保回避</td><td>値型・スタック配置(C++の既定)</td></tr><tr><td>文字列連結を避ける・StringBuilder</td><td>string領域の再利用・reserve</td></tr><tr><td>クロージャ/LINQのAlloc回避</td><td>ラムダは元々スタック(→ <a href="/study/languages/cpp/lambdas-and-functions.html">ラムダ</a>)</td></tr><tr><td><code>stackalloc</code> / <code>Span&lt;T&gt;</code></td><td>ローカル配列 / <code>std::span</code></td></tr></tbody></table><p>つまり**「Unityで最適化のためにやらされていたこと」は、C++の標準的なメモリ設計そのもの**。C#を頑張って書くほどC++の考え方に近づいていた、と言えます。</p><h2 id="c-にgcを入れる選択肢は" tabindex="-1">C++にGCを入れる選択肢は? <a class="header-anchor" href="#c-にgcを入れる選択肢は" aria-label="Permalink to &quot;C++にGCを入れる選択肢は?&quot;">​</a></h2><ul><li>技術的には存在する(Boehm GC、参照カウントの徹底=Objective-C的方式)。UEは<strong>UObjectに限定したマーク&amp;スイープGC</strong>を自作している(→ <a href="/study/game/unreal/gc-and-object-pointers.html">第10部</a>)——「ゲームオブジェクトの複雑な所有関係」にはGCが合理的、という設計判断</li><li>全域GCをC++で使わない理由: 決定性の喪失、ポインタの自由(GCはどこがポインタか知る必要がある)、RAIIとの相性——<strong>C++の強みを消してまで得るものが少ない</strong></li></ul><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「C++は毎回deleteを書く言語」— 現代C++はRAIIで<strong>書かない</strong>(→ <a href="/study/languages/cpp/raii.html">RAII</a>)。手で書くならC++を間違えている</li><li>「GCがない=リークまみれ」— 型に組み込まれた解放は、手動Disposeより漏れにくい面すらある</li><li>「GCは遅い」— 確保は速い。問題は<strong>一時停止のタイミングを選べない</strong>こと。リアルタイム性との相性の問題であり、スループットではGCが勝つ場面もある</li><li>UEに行くと「C++なのにGCがある」——UObject層だけの話で、通常のC++オブジェクトはRAIIの世界(2層構造を混同しない)</li></ol><h2 id="使い分けの視点-まとめ" tabindex="-1">使い分けの視点(まとめ) <a class="header-anchor" href="#使い分けの視点-まとめ" aria-label="Permalink to &quot;使い分けの視点(まとめ)&quot;">​</a></h2><ul><li>「フレームレートの決定性」が最優先(アクション、VR)→ C++的手法(または C# でもゼロアロケ設計)</li><li>開発速度・安全性優先のツール・ロジック層 → GCの世界観で書いてよい</li><li>どちらの世界でも: <strong>寿命のパターン(同寿命・同サイズ・フレーム限り)を見つけて構造化する</strong>のが上級者の共通技法</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>C#の管理ヒープの確保が速い理由と、その代金はどこで払われますか。</li><li>C++とC#の「うっかり」の対称性(早死に/不死)を説明できますか。</li><li>UnityのGC Alloc対策とC++のメモリ設計の対応を2つ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>自分のUnityプロジェクトで過去にやったGC Alloc対策を3つ思い出し、それぞれ「C++ならどう書くか」(このページの対応表の語彙で)を書いてください。</p><hr><p>前: <a href="/study/runtime/memory/allocators-and-pools.html">placement new・allocator・pool・arena</a> | <a href="/study/runtime/memory/">カテゴリ目次</a> | 次: <a href="/study/runtime/memory/exercises.html">演習</a></p>',24)])])}const u=a(l,[["render",n]]);export{m as __pageData,u as default};
